{
  "claims": [
    {
      "claim": "JH69U1 无法清洗拖布时，需检查清水箱及其过滤管",
      "verdict": "unsupported",
      "evidence_index": null,
      "reason": "检索片段仅描述定期清理清水箱过滤管，并未说明该操作与“无法清洗拖布”故障的因果关系。"
    },
    {
      "claim": "取出清水箱，拔出过滤管；抠开滤盖，清洗滤盖和海绵网；清理完毕后，重新装回过滤管",
      "verdict": "supported",
      "evidence_index": [1],
      "reason": "说明书第12页明确给出了这些清洗过滤管的操作步骤。"
    },
    {
      "claim": "请检查并补充清水箱水量",
      "verdict": "supported",
      "evidence_index": [5],
      "reason": "故障排除部分明确包含“请检查并补充清水箱水量”。"
    },
    {
      "claim": "请确认拖布已装好",
      "verdict": "supported",
      "evidence_index": [5],
      "reason": "故障排除部分明确出现“请确认拖布已装好”和“请及时检查并确认拖布已安装好”。"
    },
    {
      "claim": "请确认清洗支架已装好且清洁干净，并确认其安装到位",
      "verdict": "supported",
      "evidence_index": [5],
      "reason": "故障排除部分包含“请确认清洗支架已装好”及“请将清洗支架清洁干净，并确认清洗支架安装到位”。"
    },
    {
      "claim": "请确认污水箱安装到位",
      "verdict": "supported",
      "evidence_index": [5],
      "reason": "故障排除部分多次出现“确认污水箱安装到位”。"
    },
    {
      "claim": "REFUSE：资料未说明“无法清洗拖布”是否与面盖、尘盒、基站清洗槽以外的其他水路部件或控制逻辑相关，亦未提供针对“清洗拖布功能失效”的专属排查步骤",
      "verdict": "supported",
      "evidence_index": null,
      "reason": "检索片段中没有关于“无法清洗拖布”专属排查步骤或上述部件关联性的说明。"
    }
  ]
}

{
  "claims": [
    {
      "claim": "在路由器设置中确认手机连接的是 2.4GHz Wi-Fi",
      "verdict": "supported",
      "evidence_index": 2,
      "reason": "片段2步骤1明确要求确认手机连接2.4GHz Wi-Fi"
    },
    {
      "claim": "该机型不支持 5GHz 单频网络",
      "verdict": "supported",
      "evidence_index": 2,
      "reason": "片段2步骤1写明RC-S200不支持5GHz单频网络"
    },
    {
      "claim": "长按回充键与电源键 3 秒直到提示音响起，机器进入配网模式，指示灯慢闪",
      "verdict": "supported",
      "evidence_index": 2,
      "reason": "片段2步骤2完全一致"
    },
    {
      "claim": "将机器人和手机移动到路由器同一房间内重新配网",
      "verdict": "supported",
      "evidence_index": 2,
      "reason": "片段2步骤3要求将机器人和手机移到同一房间重新配网"
    },
    {
      "claim": "避开微波炉等干扰源",
      "verdict": "supported",
      "evidence_index": 2,
      "reason": "片段2步骤3写明避开微波炉等干扰源"
    },
    {
      "claim": "配网失败时请优先使用 2.4GHz 网络",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段1首句即为此内容"
    },
    {
      "claim": "将机器移至路由器附近",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段1首句提到将机器移至路由器附近"
    },
    {
      "claim": "进入配网模式需按说明书指定的组合键长按 3 秒",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段1写明按说明书指定的组合键长按3秒"
    },
    {
      "claim": "指示灯慢闪或语音提示后在 App 按引导操作",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段1写明指示灯慢闪或语音提示后在App按引导操作"
    },
    {
      "claim": "路由器建议关闭 AP 隔离与访客网络限制",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段1写明路由器建议关闭AP隔离与访客网络限制"
    },
    {
      "claim": "Wi-Fi 名称避免特殊符号",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段1写明Wi-Fi名称避免特殊符号"
    },
    {
      "claim": "双频合一路由建议临时拆分名称",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段1写明双频合一路由建议临时拆分名称"
    },
    {
      "claim": "在 App 中删除旧设备记录后重新扫码可解决大部分绑定异常",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段1写明删除旧设备记录后重新扫码可解决大部分绑定异常"
    },
    {
      "claim": "以上步骤全部执行后问题仍存在的，请停止自助排查并联系官方售后",
      "verdict": "uncheckable",
      "evidence_index": null,
      "reason": "属于请联系售后的兜底话术，非事实性论断"
    }
  ]
}

